{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Downweight frequent historical items using training-only normalized log frequencies. Apply the fixed factor 1-0.3*f_i only to input item embeddings. Preserve learned embeddings, positions, causal convolutions, readout, loss and optimizer. The persistent frequency buffer is saved in each category checkpoint; the existing predictor writer imports the updated model class and restores that buffer automatically.",
      "edits": [
        {
          "find": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)\n        self.pos_emb = nn.Embedding(maxlen + 1, hidden_units, padding_idx=0)",
          "replace": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)\n        self.register_buffer(\"input_item_frequency\", torch.zeros(itemnum + 1))\n        self.pos_emb = nn.Embedding(maxlen + 1, hidden_units, padding_idx=0)"
        },
        {
          "find": "        x = self.item_emb(seq) * (self.hidden_units ** 0.5) + self.pos_emb(pos)",
          "replace": "        input_scale = (1.0 - 0.3 * self.input_item_frequency[seq]).unsqueeze(-1)\n        x = self.item_emb(seq) * input_scale * (self.hidden_units ** 0.5) + self.pos_emb(pos)"
        },
        {
          "find": "    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)",
          "replace": "    item_counts = np.zeros(itemnum + 1, dtype=np.float64)\n    for history in user_train.values():\n        np.add.at(item_counts, np.asarray(history, dtype=np.int64), 1.0)\n    item_frequency = np.log1p(item_counts)\n    item_frequency[0] = 0.0\n    item_frequency /= max(float(item_frequency.max()), 1e-12)\n    with torch.no_grad():\n        model.input_item_frequency.copy_(torch.as_tensor(\n            item_frequency, dtype=model.input_item_frequency.dtype, device=device\n        ))\n    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)"
        }
      ]
    }
  ],
  "change_summary": "Add training-only frequency scaling to historical item embeddings for all four category models, with checkpoint-backed inference consistency and unchanged candidate embeddings."
}
